            zh: '原因二（践踏蓄奴习俗与逼签夺权通告）：Birch 擅自窝藏逃跑女奴干涉马来习俗，并威逼苏丹阿都拉签下《1875 年 11 月 2 日全面移交征税行政权公告》，否则废黜王位！',
