            zh: '⚠️ 结局必记：英国再次搬出苏丹名义瓦解民众抵抗，枪杀 11 名农民；Haji Abdul Rahman Limbong 被捕后被流放至圣城麦加（dibuang negeri ke Mekah），并于 1929 年在麦加归真。',
